import {valid} from './fixture/cases.ts';
const [entry,mode='all',countText='300',batchText='7']=process.argv.slice(2);
const {createFixture,invoke}=await import(entry);
// Independent fixtures reset result each call. Explicit/default/config switching is asserted before timing.
const fixture=createFixture();
for(let round=0;round<2;round++)for(const test of valid){assert.deepEqual(await fixture.invoke([...test.argv]),test.expected);assert.deepEqual(await fixture.invoke([...valid[0].argv]),valid[0].expected);}
const count=Number(countText),batches=Number(batchText),warmups=3,rows=[];
let last;
for(const kind of (mode==='all'?['construction','first','reused','fresh']:[mode]))for(const test of (kind==='construction'?[valid[1]]:[valid[0],valid[1],valid[5]])){
 const expected=JSON.stringify(test.expected),samples=[];
 for(let batch=0;batch<warmups+batches;batch++){
  // Construction is excluded only for the explicitly labeled first-execute diagnostic.
  const prepared=kind==='first'?Array.from({length:count},()=>createFixture()):undefined;
  const start=performance.now();
  for(let i=0;i<count;i++){
   if(kind==='construction'){last=createFixture(); if(typeof last.app.execute!=='function')throw Error('bad construction');continue;}
   const result=await (kind==='first'?prepared[i].invoke([...test.argv]):kind==='reused'?fixture.invoke([...test.argv]):invoke([...test.argv]));
   if(JSON.stringify(result)!==expected)throw Error('wrong result');
  }
  if(batch>=warmups)samples.push((performance.now()-start)*1e6/count);
 }
 rows.push({kind,case:test.name,nsPerInvocation:samples});
}
// Make the construction result observable without projecting/preparing snapshots inside the timer.
if(last)assert.deepEqual(await last.invoke([...valid[0].argv]),valid[0].expected);
console.log(JSON.stringify({count,warmups,rows}));

