  n=(len(a)-1)*p;lo=int(n);return a[lo]+(a[min(lo+1,len(a)-1)]-a[lo])*(n-lo)
 return {'median':q(.5),'p05':q(.05),'p95':q(.95),'min':min(a),'max':max(a)}
summary={'warm':[],'startup':[],'lifetime':[],'profiles':[],'profileOverhead':[]}
